7	import type React from 'react';
8	import { useCallback, useEffect, useId, useRef, useState } from 'react';
9	import { Box, Text, ResizeObserver, type DOMElement } from 'ink';
10	import { theme } from '../../semantic-colors.js';
11	import { useOverflowActions } from '../../contexts/OverflowContext.js';
