13	/**
14	 * Minimum height for the MaxSizedBox component.
15	 * This ensures there is room for at least one line of content as well as the
16	 * message that content was truncated.
17	 */
18	export const MINIMUM_MAX_HEIGHT = 2;
19	
20	interface MaxSizedBoxProps {
21	  children?: React.ReactNode;
22	  maxWidth?: number;
23	  maxHeight?: number;
24	  overflowDirection?: 'top' | 'bottom';
25	  additionalHiddenLinesCount?: number;
26	}
27	
28	/**
29	 * A React component that constrains the size of its children and provides
30	 * content-aware truncation when the content exceeds the specified `maxHeight`.
31	 */
32	export const MaxSizedBox: React.FC<MaxSizedBoxProps> = ({
33	  children,
34	  maxWidth,
35	  maxHeight,
36	  overflowDirection = 'top',
37	  additionalHiddenLinesCount = 0,
38	}) => {
39	  const id = useId();
40	  const { addOverflowingId, removeOverflowingId } = useOverflowActions() || {};
41	  const observerRef = useRef<ResizeObserver | null>(null);
42	  const [contentHeight, setContentHeight] = useState(0);
43	
44	  const onRefChange = useCallback(
45	    (node: DOMElement | null) => {
46	      if (observerRef.current) {
47	        observerRef.current.disconnect();
48	        observerRef.current = null;
49	      }
50	
51	      if (node && maxHeight !== undefined) {
52	        const observer = new ResizeObserver((entries) => {
53	          const entry = entries[0];
54	          if (entry) {
55	            setContentHeight(Math.round(entry.contentRect.height));
56	          }
57	        });
58	        observer.observe(node);
59	        observerRef.current = observer;
60	      }
61	    },
62	    [maxHeight],
63	  );
64	
65	  const effectiveMaxHeight =
66	    maxHeight !== undefined
67	      ? Math.max(Math.round(maxHeight), MINIMUM_MAX_HEIGHT)
68	      : undefined;
69	
70	  const isOverflowing =
71	    (effectiveMaxHeight !== undefined && contentHeight > effectiveMaxHeight) ||
72	    additionalHiddenLinesCount > 0;
73	
74	  // If we're overflowing, we need to hide at least 1 line for the message.
75	  const visibleContentHeight =
76	    isOverflowing && effectiveMaxHeight !== undefined
77	      ? effectiveMaxHeight - 1
78	      : effectiveMaxHeight;
79	
80	  const hiddenLinesCount =
81	    visibleContentHeight !== undefined
82	      ? Math.max(0, contentHeight - visibleContentHeight)
83	      : 0;
84	
85	  const totalHiddenLines = hiddenLinesCount + additionalHiddenLinesCount;
86	
87	  useEffect(() => {
88	    if (totalHiddenLines > 0) {
89	      addOverflowingId?.(id);
90	    } else {
91	      removeOverflowingId?.(id);
92	    }
93	
94	    return () => {
95	      removeOverflowingId?.(id);
96	    };
97	  }, [id, totalHiddenLines, addOverflowingId, removeOverflowingId]);
98	
99	  if (effectiveMaxHeight === undefined) {
100	    return (
101	      <Box flexDirection="column" width={maxWidth}>
102	        {children}
103	      </Box>
104	    );
105	  }
106	
107	  const offset =
108	    hiddenLinesCount > 0 && overflowDirection === 'top' ? -hiddenLinesCount : 0;
109	
110	  return (
111	    <Box
112	      flexDirection="column"
113	      width={maxWidth}
114	      maxHeight={effectiveMaxHeight}
115	      flexShrink={0}
116	    >
117	      {totalHiddenLines > 0 && overflowDirection === 'top' && (
118	        <Text color={theme.text.secondary} wrap="truncate">
119	          ... first {totalHiddenLines} line{totalHiddenLines === 1 ? '' : 's'}{' '}
120	          hidden ...
121	        </Text>
122	      )}
123	      <Box
124	        flexDirection="column"
125	        overflow="hidden"
126	        flexGrow={0}
127	        maxHeight={isOverflowing ? visibleContentHeight : undefined}
128	      >
129	        <Box
130	          flexDirection="column"
131	          ref={onRefChange}
132	          flexShrink={0}
133	          marginTop={offset}
134	        >
135	          {children}
136	        </Box>
137	      </Box>
138	      {totalHiddenLines > 0 && overflowDirection === 'bottom' && (
139	        <Text color={theme.text.secondary} wrap="truncate">
140	          ... last {totalHiddenLines} line{totalHiddenLines === 1 ? '' : 's'}{' '}
141	          hidden ...
142	        </Text>
143	      )}
144	    </Box>
145	  );
146	};
